'use strict'

import fs from 'fs'
import path from 'path'
import vm from 'vm'
import { declaredPackageJsonType } from '../../../esbuild/project-sweep.js'

/**
 * The path of a web app's `entry` inside its zip: POSIX separators, no
 * leading `./`.
 *
 * @param {string} entry - `webApps.<name>.entry` as configured
 * @returns {string}
 */
export function normalizeEntryPath(entry) {
  return path.posix.normalize(entry.replace(/\\/g, '/'))
}

/**
 * V8's errors for ES module syntax in a script, as Node's own detection reads
 * them: `import`, `export`, `import.meta` and top-level `await`.
 */
const ESM_SYNTAX_ERROR =
  /^(Cannot use import statement outside a module|Unexpected token 'export'|Cannot use 'import\.meta' outside a module|await is only valid in async functions and the top level bodies of modules)$/

/**
 * Whether a file's source is written as an ES module: it fails to parse as a
 * script because of `import`, `export`, `import.meta` or top-level `await`.
 * Parsed only, never run. TypeScript is parsed as is (stripping types needs
 * an experimental Node API), so a `.ts` entry with TypeScript syntax before
 * its first `import` or `export` reads as CommonJS; the entry still starts,
 * only a throw while it loads is reported differently.
 */
function isWrittenAsEsm(sourceFile) {
  let source
  try {
    source = fs.readFileSync(sourceFile, 'utf8')
  } catch {
    return false
  }
  try {
    new vm.Script(source, { filename: sourceFile })
    return false
  } catch (error) {
    // Compared by name: the error can come from another realm (a test runner's)
    return error?.name === 'SyntaxError' && ESM_SYNTAX_ERROR.test(error.message)
  }
}

/**
 * The module system Node loads a web app's entry with, for an entry the
 * Framework does not build: `.cjs`, `.cts`, `.mjs` and `.mts` name it, and
 * any other file follows the `type` of its nearest package.json, from the
 * entry's directory up to the service directory. When none declares a `type`, Node detects the
 * syntax, and so does this: a file that only parses as an ES module is one.
 *
 * @param {string} serviceDir - absolute path of the service directory
 * @param {string} entryPath - POSIX path of the entry, relative to `serviceDir`
 * @returns {'cjs'|'esm'}
 */
export function getEntryFormat(serviceDir, entryPath) {
  const extension = path.posix.extname(entryPath)
  if (extension === '.cjs' || extension === '.cts') return 'cjs'
  if (extension === '.mjs' || extension === '.mts') return 'esm'
  const declared = declaredPackageJsonType(serviceDir, entryPath)
  if (declared !== undefined) return declared === 'module' ? 'esm' : 'cjs'
  return isWrittenAsEsm(path.join(serviceDir, ...entryPath.split('/')))
    ? 'esm'
    : 'cjs'
}

/**
 * Source of the module the runtime starts (`__sls_web_bootstrap.mjs` at the
 * zip root). Lambda only sets `AWS_LAMBDA_HTTP_ENDPOINT` (`host:port`), while
 * most Node servers read `PORT` and Next.js standalone also reads `HOSTNAME`,
 * so the bootstrap sets both. It then starts the web app's entry as the main
 * module: the runtime loads the bootstrap with `import()`, so a server that
 * listens only when its file is the main module (`require.main === module`, or
 * `import.meta.url` compared with `process.argv[1]`) would otherwise never
 * start.
 *
 * @param {object} params
 * @param {string} params.entryPath - POSIX path of the entry, relative to the zip root
 * @param {'cjs'|'esm'} params.entryFormat - the module system Node loads the
 *   entry with
 * @param {boolean} params.enableSourceMaps - enable source maps in the process
 *   (never through `NODE_OPTIONS`, which on Web Functions replaces the default
 *   V8 heap size)
 * @returns {string}
 */
export function generateBootstrap({
  entryPath,
  entryFormat,
  enableSourceMaps,
}) {
  const start =
    entryFormat === 'cjs'
      ? [
          '// Lambda imports the entrypoint, so require.main is otherwise undefined:',
          '// start the CommonJS entry as the main module. Module.runMain is not part',
          "// of Node's documented API, so it is feature-detected. With an --import or",
          '// --loader preload, runMain loads the entry without waiting for it, and a',
          '// throw while it loads is reported as an exit, not an init error: the',
          '// server starting matters more.',
          "if (typeof Module.runMain === 'function') {",
          '  Module.runMain()',
          '} else {',
          '  await import(pathToFileURL(entry).href)',
          '}',
        ]
      : ['await import(pathToFileURL(entry).href)']
  return [
    '// Generated by the Serverless Framework: sets PORT and HOSTNAME from the',
    '// Lambda listen address, then starts the web app.',
    ...(entryFormat === 'cjs' ? ["import Module from 'node:module'"] : []),
    "import { dirname, join } from 'node:path'",
    "import { fileURLToPath, pathToFileURL } from 'node:url'",
    '',
    ...(enableSourceMaps ? ['process.setSourceMapsEnabled(true)', ''] : []),
    'const endpoint = process.env.AWS_LAMBDA_HTTP_ENDPOINT',
    "const separator = endpoint ? endpoint.lastIndexOf(':') : -1",
    'if (separator !== -1) {',
    '  // An IPv6 host comes in brackets ([::]:3000); listen() takes it without',
    "  process.env.HOSTNAME = endpoint.slice(0, separator).replace(/^\\[(.*)\\]$/, '$1')",
    '  process.env.PORT = endpoint.slice(separator + 1)',
    '}',
    '',
    'const root = dirname(fileURLToPath(import.meta.url))',
    `const entry = join(root, ${JSON.stringify(entryPath)})`,
    '// The entry is the main script, as when Node runs it directly',
    'process.argv[1] = entry',
    ...start,
    '',
  ].join('\n')
}
